7	pub struct PagePool {
8	    inner: Arc<PagePoolInner>,
9	}
10	
11	#[derive(Debug)]
12	struct PagePoolInner {
13	    capacity_pages: usize,
14	    free_list: Mutex<Vec<PageId>>,
15	}
16	
17	/// A set of pages leased from a [`PagePool`]. Pages return automatically on drop.
18	#[derive(Debug)]
19	pub struct OwnedPagePermit {
20	    inner: Arc<PagePoolInner>,
21	    pages: Vec<PageId>,
22	}
23	
24	/// Opaque page identifier within a pool.
25	#[derive(Clone, Copy, Debug, Eq, PartialEq, Hash)]
26	pub struct PageId(usize);
27	
28	impl PageId {
29	    pub(crate) fn index(self) -> usize {
30	        self.0
31	    }
32	}
33	
34	impl PagePool {
35	    pub(crate) fn new(capacity_pages: usize) -> Self {
36	        let free_list = (0..capacity_pages).rev().map(PageId).collect();
37	        Self {
38	            inner: Arc::new(PagePoolInner {
39	                capacity_pages,
40	                free_list: Mutex::new(free_list),
41	            }),
42	        }
43	    }
44	
45	    pub(crate) fn try_acquire_many(&self, n: usize) -> Option<OwnedPagePermit> {
46	        if n == 0 {
47	            return Some(OwnedPagePermit {
48	                inner: Arc::clone(&self.inner),
49	                pages: Vec::new(),
50	            });
51	        }
52	
53	        let mut free_list = self.inner.free_list.lock();
54	        if free_list.len() < n {
55	            return None;
56	        }
57	
58	        let mut pages = Vec::with_capacity(n);
59	        for _ in 0..n {
60	            pages.push(free_list.pop().expect("free_list length checked above"));
61	        }
62	
63	        Some(OwnedPagePermit {
64	            inner: Arc::clone(&self.inner),
65	            pages,
66	        })
67	    }
68	
69	    pub(crate) fn capacity_pages(&self) -> usize {
70	        self.inner.capacity_pages
71	    }
72	
73	    pub(crate) fn available_pages(&self) -> usize {
74	        self.inner.free_list.lock().len()
75	    }
76	}
77	
78	impl OwnedPagePermit {
79	    pub(crate) fn pages(&self) -> &[PageId] {
80	        &self.pages
81	    }
82	
83	    // `is_empty` was dead code (hawk sweep, #743); `len` stands alone.
84	    #[allow(clippy::len_without_is_empty)]
85	    pub(crate) fn len(&self) -> usize {
86	        self.pages.len()
87	    }
88	
89	    /// Both permits must lease from the same pool; merging across pools would
90	    /// return pages to the wrong free list.
91	    pub(crate) fn absorb(&mut self, mut other: OwnedPagePermit) {
92	        assert!(
93	            Arc::ptr_eq(&self.inner, &other.inner),
94	            "absorb requires permits from the same pool"
95	        );
96	        self.pages.append(&mut other.pages);
97	    }
98	
99	    /// Try to acquire `n` more pages, appending them to this permit.
100	    /// Returns `true` on success. On failure the permit is unchanged.
101	    pub(crate) fn try_grow(&mut self, n: usize) -> bool {
102	        if n == 0 {
103	            return true;
104	        }
105	
106	        let mut free_list = self.inner.free_list.lock();
107	        if free_list.len() < n {
108	            return false;
109	        }
110	
111	        self.pages.reserve(n);
112	        for _ in 0..n {
113	            self.pages
114	                .push(free_list.pop().expect("free_list length checked above"));
115	        }
116	        true
117	    }
118	}
119	
120	impl Drop for OwnedPagePermit {
121	    fn drop(&mut self) {
122	        if self.pages.is_empty() {
123	            return;
124	        }
125	
126	        let pages = std::mem::take(&mut self.pages);
127	        let mut free_list = self.inner.free_list.lock();
128	        free_list.extend(pages.into_iter().rev());
129	    }
130	}
131	
132	#[cfg(test)]
133	mod tests {
134	    use super::PageId;
135	    use super::PagePool;
136	
137	    #[test]
138	    fn acquires_pages_and_restores_on_drop() {
139	        let pool = PagePool::new(4);
140	        assert_eq!(pool.capacity_pages(), 4);
141	
142	        {
143	            let permit = pool.try_acquire_many(2).expect("acquire should succeed");
144	            assert_eq!(permit.len(), 2);
145	            assert_eq!(permit.pages(), &[PageId(0), PageId(1)]);
146	            assert_eq!(pool.available_pages(), 2);
147	
148	            let permit_b = pool
149	                .try_acquire_many(1)
150	                .expect("second acquire should succeed");
151	            assert_eq!(permit_b.pages(), &[PageId(2)]);
152	            assert_eq!(pool.available_pages(), 1);
153	        }
154	
155	        assert_eq!(pool.available_pages(), 4);
156	        let permit = pool
157	            .try_acquire_many(4)
158	            .expect("released pages should be reusable");
159	        assert_eq!(
160	            permit.pages(),
161	            &[PageId(0), PageId(1), PageId(2), PageId(3)]
162	        );
163	    }
164	
165	    #[test]
166	    fn reports_insufficient_capacity_with_none() {
167	        let pool = PagePool::new(2);
168	        let _permit = pool.try_acquire_many(1).expect("acquire should succeed");
169	
170	        assert!(pool.try_acquire_many(2).is_none());
171	    }
172	
173	    #[test]
174	    fn try_grow_extends_permit_and_returns_all_on_drop() {
175	        let pool = PagePool::new(4);
176	
177	        {
178	            let mut permit = pool.try_acquire_many(1).expect("initial acquire");
179	            assert_eq!(permit.pages(), &[PageId(0)]);
180	
181	            assert!(permit.try_grow(2));
182	            assert_eq!(permit.pages(), &[PageId(0), PageId(1), PageId(2)]);
183	            assert_eq!(pool.available_pages(), 1);
184	
185	            // grow beyond remaining capacity fails, permit unchanged
186	            assert!(!permit.try_grow(2));
187	            assert_eq!(permit.len(), 3);
188	            assert_eq!(pool.available_pages(), 1);
189	        }
190	
191	        // all 4 pages back after drop
192	        assert_eq!(pool.available_pages(), 4);
193	    }
194	}
